const list = (v, key) => Array.isArray(v) ? v : (v && Array.isArray(v[key]) ? v[key] : []);
const rowVals = (r) => (r && Array.isArray(r.values) ? (Array.isArray(r.values[0]) ? r.values[0] : r.values) : Array.isArray(r) ? r : []);
const str = (v) => (v === null || v === undefined ? "" : String(v)).trim();
const toISO = (v) => {
  const s = str(v);
  if (!s) return null;
  if (/^\d+(\.\d+)?$/.test(s)) { const n = Number(s); if (n < 20000 || n > 80000) return null; return new Date(Date.UTC(1899, 11, 30) + Math.round(n) * 86400000).toISOString().slice(0, 10); }
  let m = /^(\d{4})-(\d{2})-(\d{2})/.exec(s); if (m) return `${m[1]}-${m[2]}-${m[3]}`;
  m = /^(\d{1,2})\/(\d{1,2})\/(\d{4})/.exec(s); if (m) return `${m[3]}-${m[1].padStart(2, "0")}-${m[2].padStart(2, "0")}`;
  return null;
};
const TYPES = ["T-SHIRT", "LONG-SLEEVE", "SWEATSHIRT", "HOODIE"];
const parseGags = (rowsIn) => list(rowsIn, "value").map((r, i) => {
  const v = rowVals(r);
  return { index: typeof r.index === "number" ? r.index : i, id: str(v[0]), text: str(v[1]) ? String(v[1]).replace(/\r\n?/g, "\n").replace(/\s+$/, "") : "", collection: str(v[2]), category: str(v[3]),
    tag12: str(v[4]), tag13: str(v[5]), stem: str(v[6]), rawStem: v[6] == null ? "" : String(v[6]), status: str(v[7]), dates: [8, 9, 10, 11].map((c) => toISO(v[c])) };
}).filter((g) => g.id);
const prefixOf = (id) => { const m = /^([A-Z]+)-(\d+)$/.exec(id); return m ? m[1] : null; };
const numOf = (id) => { const m = /^([A-Z]+)-(\d+)$/.exec(id); return m ? Number(m[2]) : 0; };
// collection name -> ID prefix, learnt from gags that have both
const prefixMap = (gags) => { const c = {}; for (const g of gags) { const p = prefixOf(g.id); if (g.collection && p) { c[g.collection] = c[g.collection] || {}; c[g.collection][p] = (c[g.collection][p] || 0) + 1; } }
  const out = {}; for (const [k, v] of Object.entries(c)) out[k] = Object.entries(v).sort((a, b) => b[1] - a[1])[0][0]; return out; };
const gags = parseGags(input.gags);
const built = new Set(list(input.reg, "value").map((r) => str(rowVals(r)[0])).filter(Boolean));
const collections = (input.lists && Array.isArray(input.lists.values) ? input.lists.values : []).map((r) => str(Array.isArray(r) ? r[0] : r)).filter(Boolean);
const categories = (input.cats && Array.isArray(input.cats.values) ? input.cats.values.slice(1) : list(input.cats, "value").map(rowVals)).map((r) => str(r[0])).filter(Boolean);
const pmap = prefixMap(gags);
let latest = null; const maxNum = {};
for (const g of gags) { for (const d of g.dates) if (d && (!latest || d > latest)) latest = d; const p = prefixOf(g.id); if (p) maxNum[p] = Math.max(maxNum[p] || 0, numOf(g.id)); }
const plus1 = latest ? new Date(Date.parse(latest + "T00:00:00Z") + 86400000).toISOString().slice(0, 10) : null;
const perCollection = {};
for (const c of collections) {
  const p = pmap[c] || null;
  const empty = p ? gags.find((g) => prefixOf(g.id) === p && !g.text) : null;
  perCollection[c] = {
    prefix: p,
    next: empty ? { mode: "fill", id: empty.id, dates: empty.dates } :
      { mode: "append", id: p ? `${p}-${String((maxNum[p] || 0) + 1).padStart(5, "0")}` : null, dates: [plus1, plus1, plus1, plus1] },
    emptyLeft: p ? gags.filter((g) => prefixOf(g.id) === p && !g.text).length : 0,
  };
}
const editable = gags.filter((g) => g.text && g.status !== "LIVE_EXISTING" && !TYPES.some((t) => built.has(`${g.id}-${t}`)))
  .map((g) => ({ id: g.id, text: g.text, collection: g.collection, category: g.category, tag12: g.tag12, tag13: g.tag13, stem: g.stem, dates: g.dates }));
// Every written gag, compact, for the app's "Check Core for problems" tool.
const all = gags.filter((g) => g.text).map((g) => ({ id: g.id, row: g.index + 2, text: g.text, stem: g.rawStem, status: g.status, t12: g.tag12, t13: g.tag13 }));
return { json: JSON.stringify({ at: Date.now(), collections, categories, perCollection, latestDate: latest, editable, all }) };

const J = (v) => (typeof v === "string" ? JSON.parse(v) : v || {});
// Work out what to write to GAG_TAGS for a Tags-page action (nothing is frozen here; freezing happens at the 08:00 build).
const t = J(input.tags).values;
const reg = new Set((J(input.reg).values || []).map(r => String(r[0])));
const act = String(input.action || ""), id = String(input.gagId || "").trim();
if (act !== "tags-save") return { op: "none", patches: [], msg: "" };
const i = t.findIndex((r, k) => k > 0 && String(r[0]) === id);
if (i < 1 || !t[i][1]) return { op: "refuse", patches: [], msg: "Gag " + id + " not found" };
const r = t[i], row = i + 1;
const live = [...reg].some(c => c.startsWith(id + "-"));
const frozen = String(r[15] || "") !== "";
const regen = String(input.regenerate) === "true";
const P = (address, values) => ({ address, body: JSON.stringify({ values }) });
if (frozen) {
  if (!regen) return { op: "refuse", patches: [], msg: id + " is already frozen. Use Regenerate first." };
  if (live) return { op: "refuse", patches: [], msg: id + " has live listings, so its tags stay as they are on Etsy." };
  return { op: "save", patches: [P(`O${row}:S${row}`, [["", "", "", "", "Regenerated from the app " + new Date().toISOString().slice(0, 10)]]), P(`N${row}`, [[false]])], msg: id + ": fresh suggestions coming" };
}
const stem = String(input.stemTag || "").replace(/\s+/g, " ").trim().slice(0, 60);
const ov = String(input.override || "").split("|").map(s => s.replace(/\s+/g, " ").trim().toLowerCase()).filter(Boolean).join("|");
const appr = String(input.approved) === "true";
return { op: "save", patches: [P(`F${row}`, [[stem]]), P(`AC${row}`, [[ov]]), P(`N${row}`, [[appr]])], msg: (appr ? "Approved " : "Saved ") + id };

const J = (v) => (typeof v === "string" ? JSON.parse(v) : v || {});
// Bite-size summary of GAG_TAGS for the app's Tags page: gags due in the next 60 days (plus anything approved and waiting).
const T = J(input.tags).values, G = J(input.gags).values, Pl = J(input.pool).values, F = J(input.prod).values;
const reg = new Set((J(input.reg).values || []).map(r => String(r[0])));
const toDate = v => { if (v === "" || v == null) return null; if (typeof v === "number") return new Date(Date.UTC(1899, 11, 30) + v * 864e5); const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(String(v)); return m ? new Date(Date.UTC(+m[1], +m[2] - 1, +m[3])) : null; };
const gh = G[0], gi = n => gh.indexOf(n), gagRow = {};
G.slice(1).forEach(r => { if (r[0]) gagRow[r[0]] = r; });
const types = ["T-SHIRT", "LONG-SLEEVE", "SWEATSHIRT", "HOODIE"];
const horizon = Date.now() + 60 * 864e5;
const split = s => String(s || "").startsWith("|") ? String(s).slice(1, -1).split("|").filter(Boolean) : [];
const items = [];
T.slice(1).forEach(r => {
  const id = String(r[0] || ""); if (!id || !r[1]) return;
  const g = gagRow[id]; if (!g) return;
  const left = types.map(t => ({ t, d: toDate(g[gi(t)]) })).filter(x => x.d && !reg.has(id + "-" + x.t)).sort((a, b) => a.d - b.d);
  if (!left.length) return;
  const frozen = String(r[15] || "") !== "";
  const pending = r[13] === true && !frozen;
  if (left[0].d.getTime() > horizon && !pending) return;
  items.push({ id, coll: r[2], type: r[1], due: left[0].d.toISOString().slice(0, 10), garments: left.map(x => x.t),
    text: String(g[gi("GAG_TEXT")] || "").replace(/\s+/g, " ").trim(), titleStem: r[4], stemTag: r[5],
    stem: frozen ? r[14] : r[6], stemProblem: frozen ? "" : r[7],
    gag5: split(frozen ? r[15] : r[11]), gag5Raw: String(frozen ? r[15] : r[11]), seas2: split(frozen ? r[16] : r[12]),
    approved: r[13] === true, frozen, live: [...reg].some(c => c.startsWith(id + "-")),
    status: r[20], notes: r[21], overlap: r[24], band: r[26], overlapDetail: r[25], context: r[27], override: r[28], freezeMsg: r[18] });
});
items.sort((a, b) => (a.due < b.due ? -1 : a.due > b.due ? 1 : 0));
const pool = {};
Pl.slice(1).forEach(r => { if (r[1] !== "GAG" || r[4] !== "Y" || r[6] !== true) return; (pool[r[0]] = pool[r[0]] || []).push({ t: r[5], c: r[2] === "Anchor" ? "A" : "F", cap: r[8] === true }); });
const prod = {};
F.slice(1).forEach(r => { const k = r[0] + "|" + r[1]; (prod[k] = prod[k] || []).push(r[3]); });
return { body: JSON.stringify({ at: new Date().toISOString(), msg: String(input.msg || ""), items, pool, prod }) };

